// Decay-scan fixtures control the clock through file mtimes, frontmatter
// dates, and seeded sidecar timestamps, never by waiting.

const DAY_MS = 86400000;

function daysAgo(days) {
    return new Date(Date.now() - days * DAY_MS);
}

// The date the scan will print for a moment in time, computed the same way
// (UTC date half of the ISO form) so expected lines are exact.
function dateOf(when) {
    return when.toISOString().slice(0, 10);
}

function setMtime(store, name, when) {
    fs.utimesSync(path.join(store.memDir, name), when, when);
}

// Seed the usage sidecar directly, bypassing the CLI, for exact timestamps
// and deliberately malformed lines.
function seedUsage(store, lines) {
    fs.mkdirSync(store.memDir, { recursive: true });
    fs.writeFileSync(usagePath(store), lines.map((l) => l + '\n').join(''), 'utf8');
}

function appliedStamp(file, when) {
    return JSON.stringify({ ts: when.toISOString(), file, kind: 'applied' });
}

function readStamp(file, when) {
    return JSON.stringify({ ts: when.toISOString(), file, kind: 'read' });
}

// `count` applied stamps for one file, the newest at `newest` and the rest
// one day apart before it. Every stamp is offset from that one instant, so
// consecutive stamps sit exactly DAY_MS apart and the tally is exactly
// `count` distinct UTC days whatever the hour the suite runs at.
function appliedDays(file, count, newest) {
    const lines = [];
    for (let i = count - 1; i >= 0; i--) {
        lines.push(appliedStamp(file, new Date(newest.getTime() - i * DAY_MS)));
    }
    return lines;
}

test('decay-scan flags a memory idle past each threshold and not one with a recent applied stamp', () => {
    const store = makeStore();
    try {
        const d90 = daysAgo(90);
        const d40 = daysAgo(40);
        const d5 = daysAgo(5);
        writeMemoryFile(store, 'idle-summ.md', '# s\n');
        setMtime(store, 'idle-summ.md', d40);
        writeMemoryFile(store, 'idle-arch.md', '# a\n');
        setMtime(store, 'idle-arch.md', d90);
        // Far past the widest threshold any tally can buy (30 + 365), so this
        // memory's absence from the list is the stamp resetting its clock and
        // never an extension that happens to cover its age.
        writeMemoryFile(store, 'fresh-applied.md', '# f\n');
        setMtime(store, 'fresh-applied.md', daysAgo(500));
        writeMemoryFile(store, 'young.md', '# y\n');
        setMtime(store, 'young.md', d5);
        seedUsage(store, [appliedStamp('fresh-applied.md', d5)]);
        const usageBefore = fs.readFileSync(usagePath(store), 'utf8');

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stderr, 'memq: usage evidence: 1 stamp across 1 file\n' + NO_DRIFT
            + pairsStoodDown(['project']),
        'the standing evidence line, the clean drift answer and the stood-down pairs heading'
            + ' are the only notes a clean store gets');
        // Exact lines: each candidate carries the evidence dates that justify
        // it, and the class-then-name order is a total order, so the output
        // is byte-stable for identical store state.
        assert.strictEqual(res.stdout,
            'summarize  idle-summ  idle 40d  applied never  edited ' + dateOf(d40) + '  read never\n'
            + 'archive  idle-arch  idle 90d  applied never  edited ' + dateOf(d90) + '  read never\n');
        assert.ok(!res.stdout.includes('fresh-applied'), 'a recent applied stamp resets the clock');
        assert.ok(!res.stdout.includes('young'), 'a recently edited memory is not idle');

        // The scan writes nothing: no stamp appears, and the sidecar is
        // byte-identical.
        assert.ok(!fs.existsSync(path.join(store.memDir, 'decay-stamp')), 'no stamp is written');
        assert.strictEqual(fs.readFileSync(usagePath(store), 'utf8'), usageBefore);
    } finally {
        rmStore(store);
    }
});

test('a read stamp never resets the decay clock; it rides along as evidence', () => {
    const store = makeStore();
    try {
        const d90 = daysAgo(90);
        const d5 = daysAgo(5);
        writeMemoryFile(store, 'read-not-applied.md', '# r\n');
        setMtime(store, 'read-not-applied.md', d90);
        seedUsage(store, [readStamp('read-not-applied.md', d5)]);

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout,
            'archive  read-not-applied  idle 90d  applied never  edited ' + dateOf(d90)
            + '  read ' + dateOf(d5) + '\n');
    } finally {
        rmStore(store);
    }
});

test('a memory under memory/archive/ is never re-flagged, even though its stamps have stopped', () => {
    const store = makeStore();
    try {
        // Archived memories stop producing stamps by design (the stamp hook
        // covers direct children of a tier dir only), so their silence must
        // not read as idleness.
        const archiveDir = path.join(store.memDir, 'archive');
        fs.mkdirSync(archiveDir, { recursive: true });
        fs.writeFileSync(path.join(archiveDir, 'old-memory.md'), '# old\n', 'utf8');
        const d200 = daysAgo(200);
        fs.utimesSync(path.join(archiveDir, 'old-memory.md'), d200, d200);

        // The control: a live idle memory in the same store is flagged, so an
        // empty result could not be hiding a scan that saw nothing at all.
        writeMemoryFile(store, 'live-idle.md', '# live\n');
        setMtime(store, 'live-idle.md', daysAgo(40));

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.match(res.stdout, /^summarize  live-idle  /m);
        assert.ok(!res.stdout.includes('old-memory'), 'the archived memory is not a candidate');
    } finally {
        rmStore(store);
    }
});

test('a malformed usage line is skipped with a note, and no read path rewrites the file', () => {
    const store = makeStore();
    try {
        // Idle far past the widest threshold a tally can buy. With a
        // skipped line in the sidecar the tier nominates nothing at all,
        // so the memory's absence from the list is the suppression; what
        // this case pins is that the damage costs a note and the tier's
        // candidates, never the scan itself, and that the read leaves the
        // file byte-identical.
        writeMemoryFile(store, 'guarded.md', '# g\n');
        setMtime(store, 'guarded.md', daysAgo(500));
        // The valid applied stamp sits after the damage: one torn append
        // costs its own line, never the stamps around it, which the
        // unstamped and prune fixtures pin from their own sides.
        seedUsage(store, ['{ this is not json', appliedStamp('guarded.md', daysAgo(5))]);
        const before = fs.readFileSync(usagePath(store), 'utf8');

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, 'a damaged sidecar never fails the scan');
        assert.match(res.stderr, /skipping malformed usage line 1/);
        assert.ok(!res.stdout.includes('guarded'), 'a tier with a skipped line nominates nothing');
        assert.match(res.stderr, /no decay candidates/);
        assert.strictEqual(fs.readFileSync(usagePath(store), 'utf8'), before,
            'the sidecar is never rewritten or truncated');
    } finally {
        rmStore(store);
    }
});

test('a skipped sidecar line suppresses a tier\'s candidates: a torn applied append buys no archive nomination', () => {
    const store = makeStore();
    try {
        writeMemoryFile(store, 'load-bearing.md', '# l\n');
        setMtime(store, 'load-bearing.md', daysAgo(500));
        // The sidecar's only line is the torn front of an applied append,
        // the state the file's lock-free writers can leave behind. The
        // reader skips it and reports the skip, so the scan holds a tally
        // it knows is partial: nominating on it would flag this memory for
        // archive on evidence the scan itself reported unread, which is
        // the expensive direction, since a candidate list is acted on
        // whole and a false never-applied ages a load-bearing memory out
        // of the store.
        seedUsage(store, ['{"ts":"2026-08-01T10:00:00.000Z","file":"load-bearing.md","kind":"appl']);

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, 'a torn line never fails the scan');
        assert.match(res.stderr, /skipping malformed usage line 1/);
        assert.strictEqual(res.stdout, '',
            'no candidate of any class from a tier whose evidence went partly unread');
        assert.match(res.stderr, /1 malformed line skipped; candidates suppressed for this tier/);

        // The control: the same store with the sidecar readable whole
        // nominates, so the empty list above is the suppression and not a
        // memory that was never due.
        seedUsage(store, []);
        const control = run(store, ['decay-scan']);
        assert.strictEqual(control.status, 0, control.stderr);
        assert.match(control.stdout, /^archive {2}load-bearing {2}idle 500d {2}applied never/m);
    } finally {
        rmStore(store);
    }
});

test('rollup candidates preserve per-key tallies and carry the evidence range', () => {
    const store = makeStore();
    try {
        const d45 = daysAgo(45);
        const d40 = daysAgo(40);
        const d35 = daysAgo(35);
        const d32 = daysAgo(32);
        const d5 = daysAgo(5);
        const entry = (key, outcome, when) => JSON.stringify({
            ts: when.toISOString(), key, outcome, summary: key + ' ' + outcome
        });
        seedJournal(store, [
            entry('old.alpha', 'pass', d40),
            entry('old.alpha', 'fail', d35),
            entry('old.alpha', 'pass', d32),
            entry('old.beta', 'fail', d45),
            entry('mixed', 'pass', d40),
            entry('mixed', 'pass', d5),
            entry('recent.only', 'pass', d5)
        ]);
        const before = fs.readFileSync(journalPath(store), 'utf8');

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        // Per-key tallies over the old entries only: mixed counts one of its
        // two entries, recent.only none, and the tallies plus the range are
        // what the replacement rollup entry must preserve.
        assert.strictEqual(res.stdout,
            'rollup  mixed  1/0 older than 30d  ' + dateOf(d40) + '..' + dateOf(d40) + '\n'
            + 'rollup  old.alpha  2/1 older than 30d  ' + dateOf(d40) + '..' + dateOf(d32) + '\n'
            + 'rollup  old.beta  0/1 older than 30d  ' + dateOf(d45) + '..' + dateOf(d45) + '\n');
        assert.strictEqual(fs.readFileSync(journalPath(store), 'utf8'), before,
            'the scan never rewrites the journal');
    } finally {
        rmStore(store);
    }
});

test('a frontmatter created date joins the idle clock in both directions', () => {
    const store = makeStore();
    try {
        const d90 = daysAgo(90);
        // A recent created date defeats an old mtime: a store copied or
        // restored with odd file times can still carry an honest age in the
        // file itself, and any evidence of recency defeats the flag.
        writeMemoryFile(store, 'kept-by-created.md',
            '---\ncreated: ' + dateOf(daysAgo(5)) + '\n---\n# kept\n');
        setMtime(store, 'kept-by-created.md', d90);
        // An old created date alongside an old mtime flags: the field's
        // presence is not itself protection.
        writeMemoryFile(store, 'old-by-created.md',
            '---\ncreated: ' + dateOf(d90) + '\n---\n# old\n');
        setMtime(store, 'old-by-created.md', d90);

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout,
            'archive  old-by-created  idle 90d  applied never  created ' + dateOf(d90)
            + '  edited ' + dateOf(d90) + '  read never\n');
        assert.ok(!res.stdout.includes('kept-by-created'), 'the recent created date resets the clock');
    } finally {
        rmStore(store);
    }
});

test('decay-scan with no store notes and exits 0; with nothing due it says no candidates', () => {
    const store = makeStore();
    try {
        const missing = run(store, ['decay-scan']);
        assert.strictEqual(missing.status, 0, 'a missing store is not an error');
        assert.strictEqual(missing.stdout, '');
        assert.match(missing.stderr, /no memory directory at/);

        writeMemoryFile(store, 'young.md', '# y\n');
        const idle = run(store, ['decay-scan']);
        assert.strictEqual(idle.status, 0, idle.stderr);
        assert.strictEqual(idle.stdout, '');
        assert.match(idle.stderr, /no decay candidates/);
        // The evidence line prints on the no-candidates path too, and a
        // store that never had a sidecar reads as absent, the healthy case.
        assert.match(idle.stderr, /^memq: usage evidence: none \(no usage\.jsonl\)$/m);
    } finally {
        rmStore(store);
    }
});

test('decay-done stamps an existing store, re-touching moves the mtime, and wrong or blocked stores exit nonzero', () => {
    const store = makeStore();
    const blocked = makeStore();
    try {
        // No store yet: refusing is the point. A stamp minted under a wrong
        // cwd would report success while the real store's stamp stays stale.
        const homeless = run(store, ['decay-done']);
        assert.strictEqual(homeless.status, 1, 'no store means no recorded pass');
        assert.strictEqual(homeless.stdout, '');
        assert.match(homeless.stderr, /no memory directory at/);

        // With the store present, the stamp appears where decayStampPath points.
        writeMemoryFile(store, 'a-memory.md', '# m\n');
        const first = run(store, ['decay-done']);
        assert.strictEqual(first.status, 0, first.stderr);
        assert.match(first.stdout, /^decay stamp touched\n$/);
        const stamp = path.join(store.memDir, 'decay-stamp');
        assert.ok(fs.statSync(stamp).isFile(), 'the stamp exists where memq.decayStampPath points');

        // The mtime is the record: age the stamp, complete another pass, and
        // the record moves to now.
        const past = daysAgo(40);
        fs.utimesSync(stamp, past, past);
        const again = run(store, ['decay-done']);
        assert.strictEqual(again.status, 0, again.stderr);
        assert.ok(Date.now() - fs.statSync(stamp).mtimeMs < 60000, 'the touch renewed the mtime');

        // A stamp that cannot be written is not a recorded pass: reporting
        // success would silence the overdue nudge for another cycle.
        fs.mkdirSync(path.join(blocked.memDir, 'decay-stamp'), { recursive: true });
        const refused = run(blocked, ['decay-done']);
        assert.strictEqual(refused.status, 1);
        assert.strictEqual(refused.stdout, '');
        // The store's own words for the state, which is what makes this
        // fixture about the guard: the write alone throws EISDIR here, so an
        // assertion on the wrapper would pass with the check removed.
        assert.match(refused.stderr, /could not touch decay stamp/);
        assert.match(refused.stderr,
            /decay-stamp exists and is not a regular file, so nothing was written to it/);
    } finally {
        rmStore(store);
        rmStore(blocked);
    }
});

test('decay thresholds are inclusive at 30 and 60 days and silent below 30', () => {
    const store = makeStore();
    try {
        const d60 = daysAgo(60);
        const d30 = daysAgo(30);
        const d29 = daysAgo(29.5);
        writeMemoryFile(store, 'edge-arch.md', '# a\n');
        setMtime(store, 'edge-arch.md', d60);
        writeMemoryFile(store, 'edge-summ.md', '# s\n');
        setMtime(store, 'edge-summ.md', d30);
        writeMemoryFile(store, 'edge-young.md', '# y\n');
        setMtime(store, 'edge-young.md', d29);

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout,
            'summarize  edge-summ  idle 30d  applied never  edited ' + dateOf(d30) + '  read never\n'
            + 'archive  edge-arch  idle 60d  applied never  edited ' + dateOf(d60) + '  read never\n');
        assert.ok(!res.stdout.includes('edge-young'), 'below 30 idle days is not a candidate');
    } finally {
        rmStore(store);
    }
});

test('each distinct applied day extends both thresholds by 30 idle days, inclusive at the boundary', () => {
    const store = makeStore();
    try {
        // Six distinct applied days buy 6 * 30 = 180 idle days on both
        // thresholds: summarize at 210, archive at 240. Each memory's mtime
        // is far older than its stamps, so the applied evidence is what sets
        // the clock and the extension at once.
        const d500 = daysAgo(500);
        const d30 = daysAgo(30);
        const a209 = daysAgo(209);
        const a210 = daysAgo(210);
        const a239 = daysAgo(239);
        const a240 = daysAgo(240);
        for (const name of ['at-209.md', 'at-210.md', 'at-239.md', 'at-240.md']) {
            writeMemoryFile(store, name, '# m\n');
            setMtime(store, name, d500);
        }
        // A memory with no applied evidence keeps the unextended ladder, so
        // an extension cannot be reading as a floor every memory gets.
        writeMemoryFile(store, 'no-tally.md', '# n\n');
        setMtime(store, 'no-tally.md', d30);
        seedUsage(store, [].concat(
            appliedDays('at-209.md', 6, a209),
            appliedDays('at-210.md', 6, a210),
            appliedDays('at-239.md', 6, a239),
            appliedDays('at-240.md', 6, a240)));

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stderr, 'memq: usage evidence: 24 stamps across 4 files\n' + NO_DRIFT
            + pairsStoodDown(['project']));
        // Both directions at both boundaries: 210 summarizes and 209 does
        // not, 240 archives and 239 is still only a summarize candidate. The
        // tally rides in the applied column, so the judgment reading the line
        // sees the evidence that bought the extension.
        assert.strictEqual(res.stdout,
            'summarize  at-210  idle 210d  applied ' + dateOf(a210)
            + ' (6d distinct)  edited ' + dateOf(d500) + '  read never\n'
            + 'summarize  at-239  idle 239d  applied ' + dateOf(a239)
            + ' (6d distinct)  edited ' + dateOf(d500) + '  read never\n'
            + 'summarize  no-tally  idle 30d  applied never  edited '
            + dateOf(d30) + '  read never\n'
            + 'archive  at-240  idle 240d  applied ' + dateOf(a240)
            + ' (6d distinct)  edited ' + dateOf(d500) + '  read never\n');
        assert.ok(!res.stdout.includes('at-209'), 'one day short of the extended threshold is no candidate');
    } finally {
        rmStore(store);
    }
});

test('the extension caps at 365 idle days, so a larger tally moves no boundary', () => {
    const store = makeStore();
    try {
        // 20 distinct days would buy 600 idle days uncapped; the cap holds
        // the extension at 365, putting summarize at 395 and archive at 425.
        // The 40-day tally proves the cap is a ceiling and not a coincidence
        // of these numbers: it lands on the identical boundary.
        const d700 = daysAgo(700);
        const c394 = daysAgo(394);
        const c395 = daysAgo(395);
        const c424 = daysAgo(424);
        const c425 = daysAgo(425);
        for (const name of ['cap-394.md', 'cap-395.md', 'cap-424.md', 'cap-425.md', 'cap-huge.md']) {
            writeMemoryFile(store, name, '# c\n');
            setMtime(store, name, d700);
        }
        seedUsage(store, [].concat(
            appliedDays('cap-394.md', 20, c394),
            appliedDays('cap-395.md', 20, c395),
            appliedDays('cap-424.md', 20, c424),
            appliedDays('cap-425.md', 20, c425),
            appliedDays('cap-huge.md', 40, c395)));

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stderr, 'memq: usage evidence: 120 stamps across 5 files\n' + NO_DRIFT
            + pairsStoodDown(['project']));
        // Both boundaries in both directions under the cap: summarize at 395
        // and not 394, archive at 425 and not 424.
        assert.strictEqual(res.stdout,
            'summarize  cap-395  idle 395d  applied ' + dateOf(c395)
            + ' (20d distinct)  edited ' + dateOf(d700) + '  read never\n'
            + 'summarize  cap-424  idle 424d  applied ' + dateOf(c424)
            + ' (20d distinct)  edited ' + dateOf(d700) + '  read never\n'
            + 'summarize  cap-huge  idle 395d  applied ' + dateOf(c395)
            + ' (40d distinct)  edited ' + dateOf(d700) + '  read never\n'
            + 'archive  cap-425  idle 425d  applied ' + dateOf(c425)
            + ' (20d distinct)  edited ' + dateOf(d700) + '  read never\n');
        assert.ok(!res.stdout.includes('cap-394'), 'the capped boundary is inclusive at 395, not 394');
    } finally {
        rmStore(store);
    }
});

test('a pinned memory is listed and counted on stderr and never a candidate; deleting the field restores candidacy', () => {
    const store = makeStore();
    try {
        const d400 = daysAgo(400);
        writeMemoryFile(store, 'pinned-old.md', '---\npinned: 2026-07-01\n---\n# p\n');
        setMtime(store, 'pinned-old.md', d400);
        // The control: an identical age without the field is an archive
        // candidate, so an absent candidate line means the pin and not a
        // scan that saw nothing.
        writeMemoryFile(store, 'loud-old.md', '# l\n');
        setMtime(store, 'loud-old.md', d400);
        const evidence = 'memq: usage evidence: none (no usage.jsonl)\n';
        const oldLine = '  idle 400d  applied never  edited ' + dateOf(d400) + '  read never\n';

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout, 'archive  loud-old' + oldLine,
            'the pinned memory is on no candidate list a prune could act on');
        assert.strictEqual(res.stderr, evidence
            + 'memq: pinned: 1 memory exempt from decay\n'
            + 'memq: pinned  pinned-old' + oldLine + NO_DRIFT
            + pairsStoodDown(['project']));

        // Revocation is deleting the field: the same memory, same age, back
        // on the archive list and out of the pinned count.
        writeMemoryFile(store, 'pinned-old.md', '# p\n');
        setMtime(store, 'pinned-old.md', d400);
        const revoked = run(store, ['decay-scan']);
        assert.strictEqual(revoked.status, 0, revoked.stderr);
        assert.strictEqual(revoked.stdout,
            'archive  loud-old' + oldLine + 'archive  pinned-old' + oldLine);
        assert.strictEqual(revoked.stderr, evidence + NO_DRIFT + pairsStoodDown(['project']),
            'nothing is pinned, so no block prints');
    } finally {
        rmStore(store);
    }
});

test('the pin is the field\'s presence: an unparseable date, an empty value, and a body mention', () => {
    const store = makeStore();
    try {
        const d400 = daysAgo(400);
        // A hand-typed date nobody validates must never decide whether the
        // pin holds: refusing it would silently age out a memory someone
        // deliberately protected.
        writeMemoryFile(store, 'dated.md', '---\npinned: 2026-07-01\n---\n# d\n');
        writeMemoryFile(store, 'garbled.md', '---\npinned: last tuesday-ish\n---\n# g\n');
        writeMemoryFile(store, 'empty.md', '---\npinned:\n---\n# e\n');
        // The other direction: the pin lives in the frontmatter block, so
        // the same text in the body is prose and pins nothing.
        writeMemoryFile(store, 'body-only.md', '# b\n\npinned: 2026-07-01\n');
        for (const name of ['dated.md', 'garbled.md', 'empty.md', 'body-only.md']) {
            setMtime(store, name, d400);
        }

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        const oldLine = '  idle 400d  applied never  edited ' + dateOf(d400) + '  read never\n';
        assert.strictEqual(res.stdout, 'archive  body-only' + oldLine,
            'a body mention is prose, not a pin');
        assert.strictEqual(res.stderr,
            'memq: usage evidence: none (no usage.jsonl)\n'
            + 'memq: pinned: 3 memories exempt from decay\n'
            + 'memq: pinned  dated' + oldLine
            + 'memq: pinned  empty' + oldLine
            + 'memq: pinned  garbled' + oldLine + NO_DRIFT
            + pairsStoodDown(['project']));
    } finally {
        rmStore(store);
    }
});

test('a future-dated applied stamp reads as zero idle days, never a negative count', () => {
    const store = makeStore();
    try {
        // A clock skew or a hand-written stamp can date applied evidence
        // ahead of now. The pinned listing is where the clamped number is
        // observable, because a negative idle count is below every threshold
        // and so reaches no candidate line, and the note is what keeps the
        // exemption itself from being silent: an unclamped memory sits
        // outside decay until its future date passes, with nothing said.
        const d400 = daysAgo(400);
        const ahead = daysAgo(-10);
        writeMemoryFile(store, 'skewed.md', '---\npinned: 2026-07-01\n---\n# s\n');
        setMtime(store, 'skewed.md', d400);
        seedUsage(store, [appliedStamp('skewed.md', ahead)]);
        // The control: an unpinned memory of the same shape is held off every
        // candidate list by the same future stamp, and its note is the only
        // sign of it.
        writeMemoryFile(store, 'skewed-loud.md', '# sl\n');
        setMtime(store, 'skewed-loud.md', d400);
        fs.appendFileSync(usagePath(store), appliedStamp('skewed-loud.md', ahead) + '\n', 'utf8');

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout, '', 'a future reference time is on no candidate list');
        assert.strictEqual(res.stderr,
            'memq: usage evidence: 2 stamps across 2 files\n'
            + 'memq: skewed has a last sign of life dated in the future;'
            + ' its idle clock reads 0 until then\n'
            + 'memq: skewed-loud has a last sign of life dated in the future;'
            + ' its idle clock reads 0 until then\n'
            + 'memq: pinned: 1 memory exempt from decay\n'
            + 'memq: pinned  skewed  idle 0d  applied ' + dateOf(ahead)
            + ' (1d distinct)  edited ' + dateOf(d400) + '  read never\n'
            + NO_DRIFT
            + pairsStoodDown(['project'])
            + 'memq: no decay candidates\n');
        assert.doesNotMatch(res.stderr, /idle -\d+d/, 'the idle clock never runs negative');
    } finally {
        rmStore(store);
    }
});

test('two scans of a store carrying pinned and extended memories are byte-identical on both streams', () => {
    const store = makeStore();
    try {
        writeMemoryFile(store, 'pinned-fact.md', '---\npinned: 2026-07-01\n---\n# p\n');
        setMtime(store, 'pinned-fact.md', daysAgo(400));
        writeMemoryFile(store, 'extended.md', '# e\n');
        setMtime(store, 'extended.md', daysAgo(300));
        writeMemoryFile(store, 'plain.md', '# p\n');
        setMtime(store, 'plain.md', daysAgo(70));
        // Three distinct applied days put summarize at 120 and archive at
        // 150, so 130 idle days holds this memory in the summarize class.
        seedUsage(store, appliedDays('extended.md', 3, daysAgo(130)));

        const first = run(store, ['decay-scan']);
        assert.strictEqual(first.status, 0, first.stderr);
        // The new lines are in the output being compared: an extended
        // candidate with its tally column, a pinned line, and the count.
        assert.match(first.stdout, /^summarize  extended  idle 130d  applied \S+ \(3d distinct\)/m);
        assert.match(first.stderr, /^memq: pinned: 1 memory exempt from decay$/m);
        const second = run(store, ['decay-scan']);
        assert.strictEqual(second.stdout, first.stdout, 'identical store state, identical stdout');
        assert.strictEqual(second.stderr, first.stderr, 'identical store state, identical stderr');
    } finally {
        rmStore(store);
    }
});

test('the frontmatter grammar decides the pin: top level pins, indented is reported, and a block that never closes is classified not at all', () => {
    const store = makeStore();
    try {
        const d400 = daysAgo(400);
        writeMemoryFile(store, 'top-level.md', '---\npinned: 2026-07-01\n---\n# t\n');
        // Indented under a key other than metadata:, so it does not pin, and
        // this memory is classified like any other. metadata: is the one map
        // whose members are the author's own keys, because that is where the
        // harness moves a top-level key it rewrites; under any other key a
        // nested field is a different key. The note is the whole difference
        // between that and silence, because somebody wrote a pin into this
        // file and would otherwise watch it age out still carrying one.
        writeMemoryFile(store, 'indented.md', '---\nprovenance:\n  pinned: 2026-07-01\n---\n# i\n');
        // Unterminated: the fence opens on the first line and never closes,
        // so no reader is entitled to any line inside it, this one included.
        // The line may be a pin or may be prose, and the pass says which
        // question it could not answer rather than classifying on a guess.
        writeMemoryFile(store, 'unterminated.md', '---\n# u\n\npinned: 2026-07-01\n\nbody\n');
        // Past the bounded head: neither the field nor the closing fence
        // below it is frontmatter this walk sees, so the block reads as one
        // that never closes and the record is unclassified for that reason.
        writeMemoryFile(store, 'faraway.md',
            '---\n' + 'filler: x\n'.repeat(45) + 'pinned: 2026-07-01\n---\n# f\n');
        for (const name of ['top-level.md', 'indented.md', 'unterminated.md', 'faraway.md']) {
            setMtime(store, name, d400);
        }

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        const oldLine = '  idle 400d  applied never  edited ' + dateOf(d400) + '  read never\n';
        // One cause, two repairs, and the pairing is the point: a record whose
        // fence stands past the bound is closed already, so telling it to add
        // a fence would close the block early and drop the pinned: below the
        // new fence into the body, retiring the record this state protects.
        const notClassified = ' opens a frontmatter block that does not close inside the first'
            + ' 40 lines, so no field inside it is read and whether it is pinned is unknown:'
            + ' not classified; ';
        const addFence = 'close the block with a --- line inside the first 40 lines, keeping'
            + ' every field the record is to carry above that line\n';
        const shorten = 'shorten the block so its closing --- sits inside the first 40 lines,'
            + ' keeping every field the record is to carry above that line\n';
        assert.strictEqual(res.stdout, 'archive  indented' + oldLine,
            'only the record whose block reads is classified');
        assert.strictEqual(res.stderr,
            'memq: usage evidence: none (no usage.jsonl)\n'
            + 'memq: faraway' + notClassified + shorten
            + 'memq: indented has a pinned: field under another key, which does not pin it;'
            + ' write it at the frontmatter block\'s top level, where it pins whether or not'
            + ' the harness then moves it under metadata:\n'
            + 'memq: unterminated' + notClassified + addFence
            + 'memq: pinned: 1 memory exempt from decay\n'
            + 'memq: pinned  top-level' + oldLine
            + 'memq: anchor drift (project tier): 2 records whose anchors could not be read\n'
            + 'memq: drift  faraway  not checked (this record\'s frontmatter could not be read)\n'
            + 'memq: drift  unterminated  not checked (this record\'s frontmatter could not be read)\n'
            + pairsStoodDown(['project']),
        'a record no reader can read is named as unchecked rather than counted clean');
    } finally {
        rmStore(store);
    }
});

// One of the frontmatter shapes Claude Code rewrites a memory file into: the
// author's keys relocated into a column-0 metadata: map with keys of the
// harness's own beside them, over an empty name:. `fields` are the author's
// own lines, in the order the fixture wants them.
//
// What this reproduces is the map, which is the whole of what the reader keys
// on. It does not stand for the harness's output generally: the added key set
// varies by harness version and by feature, the majority of records on a real
// machine carry a populated name: and a top-level description: instead of this
// variant's empty one (harnessNamed below is that shape), and real records are
// CRLF where this is LF. Each of those differences has its own case, because a
// helper that claimed to be the shape would put every one of them beyond
// testing.
function harnessShaped(fields, body) {
    // The trailing space after `metadata:` is the harness's own output, kept
    // here because it is what a real record on disk carries: a map recogniser
    // that demanded a bare key would pass every fixture and fail every file.
    return '---\nname: ""\nmetadata: \n'
        + fields.map((f) => '  ' + f + '\n').join('')
        + '  node_type: memory\n'
        + '  originSessionId: ' + FIXTURE_SESSION_ID + '\n'
        + '  modified: 2026-08-23T10:11:12.345Z\n'
        + '---\n' + body;
}

// A session id shaped like the harness's own and belonging to no session. The
// fixtures need the field's shape and never its value, and a real id pasted
// here would be a live identifier of one machine's session committed into a
// repository that syncs.
const FIXTURE_SESSION_ID = '00000000-0000-4000-8000-000000000000';

// The variant most records on a real machine carry: the same column-0
// metadata: map, with the record's own name at the top level, a description:
// beside it, and a type: among the harness's keys. Nothing in the reader tests
// for any of those, which is what this fixture exists to keep true: the
// promotion is the map's doing, so a harness that adds a key or fills a
// different one changes nothing here.
function harnessNamed(name, fields, body) {
    return '---\nname: ' + name + '\ndescription: a record the harness named\nmetadata:\n'
        + fields.map((f) => '  ' + f + '\n').join('')
        + '  type: memory\n'
        + '  node_type: memory\n'
        + '  originSessionId: ' + FIXTURE_SESSION_ID + '\n'
        + '---\n' + body;
}

test('a tags key nested under metadata is the author\'s own key and is read', () => {
    const store = makeStore();
    try {
        // On Claude Code a Write into a project's memory directory is
        // rewritten in the same second into this shape, every top-level key
        // the author typed moving under metadata:. So a tags: found there is
        // the line the author wrote, and reading it is reading the file as it
        // says.
        writeMemoryFile(store, 'nested-tags.md',
            harnessShaped(['tags: gotcha, environment'], '\nbody\n'));
        const res = run(store, ['find', 'nested-tags', '--memories']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout, 'nested-tags  [gotcha,environment]  \n' + REMINDER + '\n',
            'the key the harness moved under metadata: carries the record\'s tags');
        // stderr carries only find's standing embedder-absence line here,
        // never a note about the placement.
        assert.doesNotMatch(res.stderr, /tag/);
    } finally {
        rmStore(store);
    }
});

test('a tags key nested under any other key is not', () => {
    const store = makeStore();
    try {
        // Nothing relocates a key under provenance:, so a tags: found there is
        // a different key rather than the author's own written loosely, and
        // promoting it would read the file as saying something it does not
        // say. A missed tag costs a search match rather than a decision, so
        // the miss is silent.
        writeMemoryFile(store, 'other-tags.md', '---\nname: other-tags\nprovenance:\n'
            + '  node_type: memory\n  tags: environment, powershell\n---\n\nbody\n');
        const res = run(store, ['find', 'other-tags', '--memories']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout, 'other-tags  []  \n' + REMINDER + '\n',
            'the nested key contributes no tags, and no note is printed for one');
        assert.doesNotMatch(res.stderr, /tag/);
    } finally {
        rmStore(store);
    }
});

test('a top-level field outranks the same field under metadata', () => {
    const store = makeStore();
    try {
        // Both placements in one file, disagreeing. A top-level line on a
        // harness-shaped record can only have been written after the rewrite,
        // by the CLI or by a hand working outside the Write tool, so it is the
        // newer intent and it wins.
        writeMemoryFile(store, 'both-tags.md',
            '---\nname: ""\ntags: newer\nmetadata:\n  tags: older\n'
            + '  node_type: memory\n---\n\nbody\n');
        const res = run(store, ['find', 'both-tags', '--memories']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout, 'both-tags  [newer]  \n' + REMINDER + '\n',
            'the top-level value is the answer and the nested one is not consulted');
    } finally {
        rmStore(store);
    }
});

test('a metadata map that is not at column 0 promotes nothing', () => {
    const store = makeStore();
    try {
        // The map is recognised by shape, and its shape is a column-0
        // metadata: line. A metadata: sitting under something else is itself a
        // nested key, so what hangs below it is two levels from the author's
        // own line and reads as absence.
        writeMemoryFile(store, 'deep-metadata.md', '---\nname: ""\nprovenance:\n'
            + '  metadata:\n    tags: gotcha\n---\n\nbody\n');
        // Deeper nesting inside a real map is not a member of it either: the
        // members are the lines at the first member's indentation, and nothing
        // below them.
        writeMemoryFile(store, 'deep-member.md', '---\nname: ""\nmetadata:\n'
            + '  node_type: memory\n  origin:\n    tags: gotcha\n---\n\nbody\n');
        const res = run(store, ['find', 'deep', '--memories']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout,
            'deep-member  []  \ndeep-metadata  []  \n' + REMINDER + '\n',
            'neither shape is the map whose members are the author\'s own keys');
    } finally {
        rmStore(store);
    }
});

test('a metadata key carrying its own value is a field, not the map', () => {
    const store = makeStore();
    try {
        // The harness writes metadata: bare, as the key a map hangs from. A
        // metadata: holding a scalar is an ordinary field somebody wrote, so
        // what sits indented below it is nested under a plain key and reads as
        // absence, exactly as it would under any other name.
        writeMemoryFile(store, 'scalar-metadata.md', '---\nname: ""\nmetadata: some note\n'
            + '  tags: gotcha\n---\n\nbody\n');
        const res = run(store, ['find', 'scalar-metadata', '--memories']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout, 'scalar-metadata  []  \n' + REMINDER + '\n',
            'a scalar-valued metadata: opens no map, so the key below it is not promoted');
    } finally {
        rmStore(store);
    }
});

// The blob SHA git computes over the six bytes `hello\n`, spelled here
// rather than derived so the state cases hold a recorded value no
// implementation detail of blobSha can move.
const HELLO_SHA = 'ce013625030ba8dba906f756967f9e9ca394464a';
const OTHER_SHA = 'b'.repeat(40);

// A project directory holding the anchor targets these cases resolve, and the
// root they resolve against. Separate from the store so a case can point an
// anchor at a path outside the root and mean it.
function makeAnchorTree() {
    const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'memq-anchor-')));
    fs.mkdirSync(path.join(root, 'src'), { recursive: true });
    fs.writeFileSync(path.join(root, 'src', 'a.js'), Buffer.from('hello\n', 'latin1'));
    fs.writeFileSync(path.join(root, 'src', 'b.js'), Buffer.from('hello\n', 'latin1'));
    return root;
}

// One parsed anchor, as parseAnchors reports it in its ordered list.
function anchorItem(p, sha) {
    return { text: p + '@' + sha, path: p, sha };
}

test('an anchors key nested under metadata is the author\'s own key and is read', () => {
    const store = makeStore();
    try {
        // The same relocation every hand-written top-level key gets on this
        // harness, so an anchors: found under the map is the line the author
        // wrote and the entries it carries are the record's anchors.
        writeMemoryFile(store, 'nested-anchors.md',
            harnessShaped(['anchors: "src/a.js@' + HELLO_SHA + '"'], '\nbody\n'));
        const got = memq.readFrontmatterAnchors(path.join(store.memDir, 'nested-anchors.md'));
        assert.deepStrictEqual(got.entries, [anchorItem('src/a.js', HELLO_SHA)]);
        assert.deepStrictEqual(got.bad, []);
        assert.strictEqual(got.truncated, false);

        // A top-level line is the same field with nothing between the author
        // and the bytes, and it reads the same.
        writeMemoryFile(store, 'top-anchors.md',
            '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + ', lib/b.js@' + OTHER_SHA
            + '\n---\n\nbody\n');
        const top = memq.readFrontmatterAnchors(path.join(store.memDir, 'top-anchors.md'));
        assert.deepStrictEqual(top.items,
            [anchorItem('src/a.js', HELLO_SHA), anchorItem('lib/b.js', OTHER_SHA)]);
    } finally {
        rmStore(store);
    }
});

test('a record that could not be read as saying anything about anchors is not a record with none', () => {
    const store = makeStore();
    const root = makeAnchorTree();
    try {
        // Nothing relocates a key under provenance:, so an anchors: found
        // there is not the field. The record still meant to anchor something,
        // and answering 'no anchors' would report it as checked and clean,
        // which is the one answer a drift surface must never give for a
        // record nobody could read.
        writeMemoryFile(store, 'other-anchors.md', '---\nname: other-anchors\nprovenance:\n'
            + '  node_type: memory\n  anchors: src/a.js@' + HELLO_SHA + '\n---\n\nbody\n');
        assert.strictEqual(memq.readFrontmatterAnchors(path.join(store.memDir, 'other-anchors.md')), null);
        assert.strictEqual(memq.anchorStates(path.join(store.memDir, 'other-anchors.md'), root), null);

        // An unreadable file is the same answer, and for the same reason.
        assert.strictEqual(memq.readFrontmatterAnchors(path.join(store.memDir, 'no-such.md')), null);
        assert.strictEqual(memq.anchorStates(path.join(store.memDir, 'no-such.md'), root), null);

        // A fence that opens and never closes inside the reader's line bound
        // is a block nobody could read. This reader consults the block, and
        // the value reader answers FRONTMATTER_UNCLOSED, so neither can give
        // the answer a record without the field gives; a block running past
        // the bound reads the same way.
        const unterminated = '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\nstill open\n';
        writeMemoryFile(store, 'unterminated.md', unterminated);
        assert.strictEqual(memq.frontmatterAnchors(unterminated), null);
        assert.strictEqual(memq.readFrontmatterAnchors(path.join(store.memDir, 'unterminated.md')), null);
        assert.strictEqual(memq.anchorStates(path.join(store.memDir, 'unterminated.md'), root), null);
        const past = '---\n' + 'filler: x\n'.repeat(60) + 'anchors: src/a.js@'
            + HELLO_SHA + '\n---\n';
        assert.strictEqual(memq.frontmatterAnchors(past), null);

        // A record carrying no fence at all is the other case: it definitely
        // names no anchor, so it is checked and clean.
        assert.deepStrictEqual(memq.frontmatterAnchors('# plain\n\nbody\n').items, []);

        // The sentinels answer at the value door too, not only at the file
        // door above it: a walk holding a record's text composes the two
        // directly, and that composition is what the read surfaces copy.
        assert.strictEqual(memq.parseAnchors(memq.FRONTMATTER_UNREADABLE), null);
        assert.strictEqual(memq.parseAnchors(memq.FRONTMATTER_INDENTED), null);
        const misplaced = '---\nname: x\nprovenance:\n  anchors: src/a.js@' + HELLO_SHA + '\n---\n';
        assert.strictEqual(memq.parseAnchors(memq.frontmatterValue(misplaced, 'anchors')), null);
        assert.strictEqual(memq.anchorStatesFrom(
            memq.parseAnchors(memq.frontmatterValue(misplaced, 'anchors')), root), null);

        // The contrast that gives those two their meaning: a record that read
        // fine and carries no anchors is checked, and answers the empty list.
        writeMemoryFile(store, 'plain.md', '---\nname: ""\ntags: a\n---\n\nbody\n');
        assert.deepStrictEqual(memq.readFrontmatterAnchors(path.join(store.memDir, 'plain.md')).items, []);
        assert.deepStrictEqual(memq.anchorStates(path.join(store.memDir, 'plain.md'), root), []);
    } finally {
        fs.rmSync(root, { recursive: true, force: true });
        rmStore(store);
    }
});

test('the list form of anchors: reads as no anchors', () => {
    const store = makeStore();
    try {
        // The field is one line, the discipline tags: already has. A YAML
        // list leaves the key carrying no value of its own, and the item
        // lines below it are not the field.
        writeMemoryFile(store, 'list-anchors.md', '---\nname: ""\nanchors:\n'
            + '  - src/a.js@' + HELLO_SHA + '\n---\n\nbody\n');
        assert.deepStrictEqual(memq.readFrontmatterAnchors(path.join(store.memDir, 'list-anchors.md')).items,
            []);
    } finally {
        rmStore(store);
    }
});

test('parseAnchors reads past a refused entry, in order, and names every one it refused', () => {
    const good = 'src/a.js@' + HELLO_SHA;
    const tail = 'lib/c.js@' + 'c'.repeat(40);
    const clean = memq.parseAnchors(good + ', ' + tail);
    assert.deepStrictEqual(clean.items,
        [anchorItem('src/a.js', HELLO_SHA), anchorItem('lib/c.js', 'c'.repeat(40))]);
    assert.deepStrictEqual(clean.bad, []);
    assert.strictEqual(clean.truncated, false);
    // A field that is absent or carries nothing is checked and clean, and
    // those are the only two readable shapes besides a value: what is
    // readable is an allowlist, so a value of some other type, a sentinel
    // this file adds later included, is not checked rather than clean.
    for (const empty of ['', '   ', ',,', null]) {
        assert.deepStrictEqual(memq.parseAnchors(empty).items, [], String(empty) + ' carries no entry');
    }
    for (const unreadable of [undefined, 7, {}, [], Symbol('a third sentinel'), () => 'x']) {
        assert.strictEqual(memq.parseAnchors(unreadable), null, String(unreadable) + ' is not readable');
    }

    // Each shape the grammar refuses, named back as the author wrote it so a
    // refusal can quote the entry rather than the whole line. The entry after
    // it is still read, and the refusal keeps its place in the line: a
    // surface saying which anchor it means counts the same positions the
    // author wrote.
    // Each shape the grammar refuses, with the fault the refusal names, so
    // a reader of the line learns why rather than only that. The entry text
    // is quoted back as written where nothing had to be reduced. Whitespace
    // is one of the reductions, since a space in a quoted path is as
    // unreadable on a report line as a zero-width one, so a row carrying it
    // names the text it is shown as.
    const notEntry = 'not <path>@<40 hex>';
    const notPath = 'the path is not one an anchor may name';
    const rejected = [
        ['src/a.js', notEntry],
        ['src/a.js@' + 'a'.repeat(39), notEntry],
        ['src/a.js@' + 'A'.repeat(40), notEntry],
        ['/src/a.js@' + HELLO_SHA, notPath],
        ['C:/src/a.js@' + HELLO_SHA, notPath],
        ['README.md::$DATA@' + HELLO_SHA, notPath],
        ['src\\a.js@' + HELLO_SHA, notPath],
        ['../src/a.js@' + HELLO_SHA, notPath],
        ['src/./a.js@' + HELLO_SHA, notPath],
        ['src//a.js@' + HELLO_SHA, notPath],
        ['@' + HELLO_SHA, notEntry],
        ['src/a.js @' + HELLO_SHA, notPath, 'src/a.js@' + HELLO_SHA],
        ['src/a b.js@' + HELLO_SHA, notPath, 'src/ab.js@' + HELLO_SHA],
        ['src/a.js@' + HELLO_SHA + '@' + HELLO_SHA, notPath],
        ['src/COM1@' + HELLO_SHA, notPath],
        ['src/CONIN$/a.js@' + HELLO_SHA, notPath],
        ['src/.../a.js@' + HELLO_SHA, notPath],
        ['src/a./b.js@' + HELLO_SHA, notPath]
    ];
    for (const [entry, fault, shown] of rejected) {
        // A row naming its display text is one the gate reduces, and the
        // reduction is named on the line beside the fault.
        const display = shown === undefined
            ? entry + ' [' + fault + ']'
            : shown + ' [characters removed for display; ' + fault + ']';
        const got = memq.parseAnchors(good + ', ' + entry + ', ' + tail);
        assert.deepStrictEqual(got.items, [
            anchorItem('src/a.js', HELLO_SHA),
            { text: display, path: null, sha: null },
            anchorItem('lib/c.js', 'c'.repeat(40))
        ], entry + ' is refused in its own place, and the entry after it is still read');
        assert.deepStrictEqual(got.bad, [display]);
    }

    // A path in a language the repository is written in is a path. Refusing
    // one would cost the file the feature and say nothing about why.
    const nonAscii = memq.parseAnchors('src/\u00dcbersicht.cs@' + HELLO_SHA);
    assert.deepStrictEqual(nonAscii.entries.map((e) => e.path), ['src/\u00dcbersicht.cs']);
    assert.deepStrictEqual(nonAscii.bad, []);

    // The comma is the line's separator, so a path may not carry one and
    // isAnchorPath refuses one that does. That closes the doors a comma can
    // be written through (the verb that writes the field and the guard that
    // screens a hand-written one, both of which refuse through this grammar),
    // and it cannot change how a line that arrives some other way reads: the
    // split runs before any path exists, so such a line is two entries by the
    // grammar's own reading, a refusal and an anchor on a path the author did
    // not write as one. That is pinned here as what it is, rather than left
    // to look like a check that holds.
    assert.strictEqual(memq.isAnchorPath('src/a,b.js'), false);
    const comma = memq.parseAnchors('src/a,b.js@' + HELLO_SHA);
    assert.deepStrictEqual(comma.bad, ['src/a [' + notEntry + ']']);
    assert.deepStrictEqual(comma.entries.map((e) => e.path), ['b.js']);

    // Two refusals are two names, in the order the line carries them.
    assert.deepStrictEqual(memq.parseAnchors('one, ' + good + ', two').bad,
        ['one [' + notEntry + ']', 'two [' + notEntry + ']']);

    // Refused text is store text bound for a report line, so it leaves here
    // reduced to what may be printed and marked where the reduction changed
    // it: quoting back text that reads valid would name something the record
    // does not say.
    assert.deepStrictEqual(memq.parseAnchors('a\u001b[31mb"c\u0007').bad,
        ['a[31mbc [characters removed for display; ' + notEntry + ']']);

    // The two reductions are different facts and are named apart. A quoted
    // line loses only its quotes, so the text left reads exactly like a valid
    // entry: without the stripping note a reader has no reason to doubt it.
    assert.deepStrictEqual(memq.parseAnchors('"' + good + '"').bad,
        [good + ' [characters removed for display; ' + notEntry + ']']);
    assert.deepStrictEqual(memq.parseAnchors('src/a\u200bb.js@' + HELLO_SHA).bad,
        ['src/ab.js@' + HELLO_SHA + ' [characters removed for display; ' + notPath + ']']);

    // Length is shown against the entry's own cap, so a refused entry with a
    // long path is not reported cut with its sha truncated away when nothing
    // exceeded that cap.
    const atCap = 'x'.repeat(249) + '*/y.js@' + HELLO_SHA;
    assert.strictEqual(memq.parseAnchors(atCap).bad[0], atCap + ' [' + notPath + ']');
    const long = memq.parseAnchors(good + ', ' + 'x'.repeat(400) + '@' + HELLO_SHA + ', ' + tail);
    assert.strictEqual(long.entries.length, 2);
    assert.strictEqual(long.bad.length, 1);
    assert.strictEqual(long.bad[0], 'x'.repeat(memq.ANCHOR_ENTRY_CAP)
        + ' [shown to ' + memq.ANCHOR_ENTRY_CAP + ' characters; longer than an entry can be]');

    // The whole value is capped before the split that reads it, and the cut
    // is reported rather than the partial piece it lands in.
    const overlong = memq.parseAnchors((good + ', ').repeat(400));
    assert.strictEqual(overlong.truncated, true);
    assert.ok(overlong.entries.every((e) => e.path === 'src/a.js'),
        'no piece cut in half is presented as an entry the record carries');

    // One record's line asks for one bounded amount of work. The cut is a
    // property of the line rather than an entry of it, so it rides as a flag
    // and no caller finds a sentence where it expected a path.
    const many = Array.from({ length: 40 }, (_, i) => 'src/f' + i + '.js@' + HELLO_SHA).join(', ');
    const capped = memq.parseAnchors(many);
    assert.strictEqual(capped.items.length, 32);
    assert.deepStrictEqual(capped.bad, []);
    assert.strictEqual(capped.truncated, true);
});

test('isAnchorPath is the one grammar, exported so the writer refuses through it', () => {
    assert.ok(memq.isAnchorPath('src/a.js'));
    assert.ok(memq.isAnchorPath('a.js'));
    // The shape a writer produces by the obvious route: path.relative answers
    // with the platform separator, and an entry written that way would be
    // refused by every reader forever.
    assert.strictEqual(path.relative(path.join('D:', 'p'), path.join('D:', 'p', 'src', 'a.js')),
        process.platform === 'win32' ? 'src\\a.js' : 'src/a.js');
    // A non-string is refused rather than thrown at: the export exists for a
    // writer holding an argument it was never given.
    for (const bad of [undefined, null, 7, {}, ['a.js']]) {
        assert.strictEqual(memq.isAnchorPath(bad), false, String(bad) + ' is not an anchor path');
    }
    // A win32 device name maps to the device from any directory, so resolving
    // one opens a serial port instead of reading a file, and the wildcard and
    // redirect set is not filename text on that platform and is shell syntax
    // wherever a path is echoed into one.
    // Characters outside ASCII are ordinary path characters and are admitted,
    // since a repository with a non-English filename is an ordinary
    // repository. What stays barred is what a reader of a report line cannot
    // see: whitespace, the control ranges, and the zero-width and
    // bidirectional formatting controls.
    for (const good of ['caf\u00e9.js', 'src/\u00dcbersicht.cs', '\u65e5\u672c\u8a9e/a.js',
        'src/na\u00efve.md', '\u00e9\u0301.js']) {
        assert.ok(memq.isAnchorPath(good), JSON.stringify(good) + ' is an anchor path');
    }
    for (const bad of ['src\\a.js', '/src/a.js', 'C:/a.js', '../a.js', './a.js', 'a//b.js',
        'a,b.js', 'a@b.js', 'a"b.js', 'a b.js', '', 'x'.repeat(257),
        'NUL', 'nul', 'src/COM1', 'src/lpt9.txt', 'CON', 'aux', 'PRN',
        'src/CONIN$', 'CONOUT$.txt', 'src/.../a.js', 'src/a./b.js', 'a.',
        'a\u00a0b.js', 'a\u200bb.js', 'a\u202eb.js', 'a\ufeffb.js', 'a\u0001b.js',
        'a*.js', 'a?.js', 'a<b.js', 'a>b.js', 'a|b.js']) {
        assert.strictEqual(memq.isAnchorPath(bad), false, JSON.stringify(bad) + ' is not an anchor path');
    }
});

test('blobSha is git\'s own hash over a file\'s literal bytes, null for anything that is not one', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'memq-blob-'));
    try {
        // git hash-object --no-filters over these exact bytes. Written as a
        // buffer so the fixture is LF on every platform: a CRLF file hashes
        // to something else, which would read as a bug in the hash.
        const file = path.join(dir, 'hello.txt');
        fs.writeFileSync(file, Buffer.from('hello\n', 'latin1'));
        assert.strictEqual(memq.blobSha(file), HELLO_SHA);

        // The bytes are hashed as they sit, never decoded: a CRLF file is a
        // different blob, exactly as git reports it with the clean filter off.
        const crlf = path.join(dir, 'hello-crlf.txt');
        fs.writeFileSync(crlf, Buffer.from('hello\r\n', 'latin1'));
        assert.notStrictEqual(memq.blobSha(crlf), HELLO_SHA);

        assert.strictEqual(memq.blobSha(path.join(dir, 'absent.txt')), null);
        assert.strictEqual(memq.blobSha(dir), null);
        assert.strictEqual(memq.blobSha(undefined), null);

        // The path comes out of a record's text, so the read is bounded: a
        // file past the cap is not hashed at all, rather than hashed over a
        // prefix that would answer 'changed' for it forever.
        const huge = path.join(dir, 'huge.bin');
        fs.writeFileSync(huge, Buffer.alloc(4194305));
        assert.strictEqual(memq.blobSha(huge), null);
    } finally {
        fs.rmSync(dir, { recursive: true, force: true });
    }
});

// Patch fstatSync in the child so that one of the two fstats blobSha takes
// on its open descriptor disagrees with the bytes it can read: 'first'
// inflates the size gate, which comes up short at the read, and 'second'
// inflates the re-check, which is the file that grew while it was read. The
// race is the whole reason blobSha reads through a descriptor, so it is
// proved the way the suite proves its other fs-layer faults, in a spawned
// child rather than by patching this process.
function growingFstatPreload(dir, which) {
    const shim = path.join(dir, 'grow-' + which + '.js');
    fs.writeFileSync(shim, [
        "'use strict';",
        "const fs = require('fs');",
        'const realFstatSync = fs.fstatSync;',
        'let calls = 0;',
        'fs.fstatSync = function () {',
        '    const st = realFstatSync.apply(fs, arguments);',
        '    calls += 1;',
        '    if (calls === ' + (which === 'first' ? '1' : '2') + ') {',
        '        return { isFile: () => st.isFile(), isDirectory: () => st.isDirectory(),',
        '            size: st.size + 10 };',
        '    }',
        '    return st;',
        '};'
    ].join('\n') + '\n', 'utf8');
    return '--require "' + shim.replace(/\\/g, '/') + '"';
}

test('blobSha answers null when the descriptor and the bytes disagree, rather than hashing a partial file', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'memq-grow-'));
    try {
        const file = path.join(dir, 'hello.txt');
        fs.writeFileSync(file, Buffer.from('hello\n', 'latin1'));
        const script = 'const m = require(' + JSON.stringify(MEMQ) + ');'
            + 'process.stdout.write(String(m.blobSha(' + JSON.stringify(file) + ')));';
        const run = (extra) => spawnSync(process.execPath, ['-e', script], {
            encoding: 'utf8',
            env: { ...scrubRunEnv({ ...process.env }), ...(extra || {}) }
        });

        // The control: unpatched, the same child hashes the file, so a null
        // below is the injected fault and not a broken spawn.
        const control = run();
        assert.strictEqual(control.status, 0, control.stderr);
        assert.strictEqual(control.stdout, HELLO_SHA);

        // Short read: the size gate says more than the file will give.
        const short = run({ NODE_OPTIONS: growingFstatPreload(dir, 'first') });
        assert.strictEqual(short.status, 0, short.stderr);
        assert.strictEqual(short.stdout, 'null');

        // Grew while read: the second fstat disagrees with the first, which
        // is what a file still being written answers. Hashing it would record
        // a value matching no state that file was ever in.
        const grew = run({ NODE_OPTIONS: growingFstatPreload(dir, 'second') });
        assert.strictEqual(grew.status, 0, grew.stderr);
        assert.strictEqual(grew.stdout, 'null');
    } finally {
        fs.rmSync(dir, { recursive: true, force: true });
    }
});

test('a non-string reaching a reader that takes text is not checked, and never throws', () => {
    const store = makeStore();
    const root = makeAnchorTree();
    try {
        // The guard this plan builds validates a Write payload through these
        // readers while holding content it has not checked, and its own
        // contract is that an unknown payload allows. A reader that raised
        // here would make that contract unkeepable.
        for (const notText of [undefined, null, 7, {}, [], Buffer.from('x'), () => 'x']) {
            assert.strictEqual(memq.frontmatterAnchors(notText), null,
                'frontmatterAnchors(' + String(notText) + ')');
            assert.strictEqual(memq.readFrontmatterAnchors(notText), null,
                'readFrontmatterAnchors(' + String(notText) + ')');
            assert.strictEqual(memq.anchorStates(notText, root), null,
                'anchorStates(' + String(notText) + ')');
            assert.strictEqual(memq.anchorStatesFrom(notText, root), null,
                'anchorStatesFrom(' + String(notText) + ')');
            assert.strictEqual(memq.isAnchorPath(notText), false,
                'isAnchorPath(' + String(notText) + ')');

            // The root derivation answers a path, so a value that is not
            // one has to answer null rather than the string that value
            // prints as: `String(7)` is a relative path, and a relative
            // path reads exactly like a root this had found.
            assert.strictEqual(memq.anchorRoot(notText), null,
                'anchorRoot(' + String(notText) + ')');
        }

        // A parse-shaped object carrying an item that is not one: the
        // in-memory form is a report path too, so it answers rather than
        // letting the throw out.
        assert.strictEqual(memq.anchorStatesFrom({ items: [null] }, root), null);
        assert.strictEqual(memq.anchorStatesFrom({ items: [{ path: 'a.js', sha: null }] }, root).length, 1);
    } finally {
        fs.rmSync(root, { recursive: true, force: true });
        rmStore(store);
    }
});

test('anchorStates reports each anchor fresh, changed, missing, or unreadable, and never throws', () => {
    const store = makeStore();
    const root = makeAnchorTree();
    try {
        writeMemoryFile(store, 'anchored.md', '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA
            + ', src/b.js@' + OTHER_SHA + ', src/gone.js@' + 'c'.repeat(40)
            + ', ../outside.js@' + 'd'.repeat(40) + '\n---\n\nbody\n');
        const file = path.join(store.memDir, 'anchored.md');
        assert.deepStrictEqual(memq.anchorStates(file, root), [
            {
                path: 'src/a.js', entry: 'src/a.js@' + HELLO_SHA,
                recorded: HELLO_SHA, current: HELLO_SHA, state: 'fresh'
            },
            {
                path: 'src/b.js', entry: 'src/b.js@' + OTHER_SHA,
                recorded: OTHER_SHA, current: HELLO_SHA, state: 'changed'
            },
            {
                path: 'src/gone.js', entry: 'src/gone.js@' + 'c'.repeat(40),
                recorded: 'c'.repeat(40), current: null, state: 'missing'
            },
            // The refused entry keeps its place and its text, and carries no
            // path: a report quotes it rather than printing it where a path
            // belongs.
            {
                path: null,
                entry: '../outside.js@' + 'd'.repeat(40)
                    + ' [the path is not one an anchor may name]',
                recorded: null, current: null, state: 'unreadable'
            }
        ]);

        // Only a path with nothing at it is a deletion. A directory where a
        // file was is a check that did not happen, and calling it 'missing'
        // would report the store's most alarming state for a cause that is
        // not one. The read cap and a permission refusal take the same route.
        // A path running through a file is the same answer on every
        // platform: the resolve reports it as ENOENT on win32 and ENOTDIR
        // elsewhere, so the state is settled by asking which parent segment
        // is not a directory rather than by the error code.
        writeMemoryFile(store, 'odd.md', '---\nname: ""\nanchors: src@' + HELLO_SHA
            + ', src/a.js/nested.js@' + HELLO_SHA + '\n---\n\nbody\n');
        assert.deepStrictEqual(memq.anchorStates(path.join(store.memDir, 'odd.md'), root), [
            { path: 'src', entry: 'src@' + HELLO_SHA, recorded: HELLO_SHA, current: null, state: 'unreadable' },
            {
                path: 'src/a.js/nested.js', entry: 'src/a.js/nested.js@' + HELLO_SHA,
                recorded: HELLO_SHA, current: null, state: 'unreadable'
            }
        ]);

        assert.strictEqual(memq.anchorStates(undefined, undefined), null);
    } finally {
        fs.rmSync(root, { recursive: true, force: true });
        rmStore(store);
    }
});

test('a root or a parse that cannot be checked answers null, never a store full of missing files', () => {
    const store = makeStore();
    const root = makeAnchorTree();
    try {
        writeMemoryFile(store, 'anchored.md',
            '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\n---\n\nbody\n');
        const file = path.join(store.memDir, 'anchored.md');

        // The control: against the real root the same record checks.
        assert.deepStrictEqual(memq.anchorStates(file, root), [{
            path: 'src/a.js', entry: 'src/a.js@' + HELLO_SHA,
            recorded: HELLO_SHA, current: HELLO_SHA, state: 'fresh'
        }]);

        // worktreeMainRoot answers null for an ordinary checkout, which is
        // most of them, so null is the value a surface reaching for the wrong
        // root will hand in. Every unusable root is 'not checked': answering
        // a list of 'missing' would report every anchored file in the store
        // as deleted over the caller's own cwd.
        for (const bad of [null, undefined, '', 'src', 42,
            path.join(root, 'no-such-dir'), path.join(root, 'src', 'a.js')]) {
            assert.strictEqual(memq.anchorStates(file, bad), null, String(bad) + ' is not a root');
        }

        // And a parse that is not one, on the surface whose whole contract is
        // that it never throws.
        for (const bad of [undefined, null, 'src/a.js@' + HELLO_SHA, {}, { items: 'no' }]) {
            assert.strictEqual(memq.anchorStatesFrom(bad, root), null, 'not a parse: ' + String(bad));
        }
    } finally {
        fs.rmSync(root, { recursive: true, force: true });
        rmStore(store);
    }
});

test('a line cut at the entry cap says so through both state forms, never as a clean list', () => {
    const store = makeStore();
    const root = makeAnchorTree();
    try {
        // The entries past the cap were never looked at, so a list of the
        // first 32 with nothing else said is a partial check wearing the
        // value of a complete one. The cut rides as one further state, the
        // only one carrying truncated, and both entry points hand it out:
        // the file-reading form holds no parse of its own for a caller to
        // consult.
        const line = Array.from({ length: 40 },
            (_, i) => 'src/f' + i + '.js@' + HELLO_SHA).join(', ');
        writeMemoryFile(store, 'many.md', '---\nname: ""\nanchors: ' + line + '\n---\n\nbody\n');
        const states = memq.anchorStates(path.join(store.memDir, 'many.md'), root);
        assert.strictEqual(states.length, 33);
        assert.deepStrictEqual(states[32], {
            path: null,
            entry: 'the rest of the line is unread past ' + memq.ANCHOR_ENTRIES_MAX + ' entries',
            recorded: null, current: null, state: 'unreadable', truncated: true
        });
        assert.ok(states.every((st) => typeof st.entry === 'string' && st.entry !== ''),
            'every row carries text a report can print, the cut row included');
        assert.strictEqual(states.filter((st) => st.truncated === true).length, 1,
            'the cut is one state and the checked anchors carry no such flag');
        assert.deepStrictEqual(
            memq.anchorStatesFrom(memq.parseAnchors(line), root), states);

        // The control: one entry under the cap is a complete check, and
        // nothing in the list says otherwise.
        const short = Array.from({ length: 32 },
            (_, i) => 'src/f' + i + '.js@' + HELLO_SHA).join(', ');
        const full = memq.anchorStatesFrom(memq.parseAnchors(short), root);
        assert.strictEqual(full.length, 32);
        assert.deepStrictEqual(full.filter((st) => st.truncated === true), []);
    } finally {
        fs.rmSync(root, { recursive: true, force: true });
        rmStore(store);
    }
});

test('an anchor reaching out of the root through a junction is unreadable, not fresh', (t) => {
    const root = makeAnchorTree();
    const outside = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'memq-outside-')));
    try {
        fs.writeFileSync(path.join(outside, 'secret.js'), Buffer.from('hello\n', 'latin1'));
        try {
            fs.symlinkSync(outside, path.join(root, 'link'), 'junction');
        } catch (err) {
            t.skip('this box refuses a junction: ' + err.code);
            return;
        }
        // The resolve is lexical and the read is not: a link inside the root
        // naming a directory outside it would otherwise be hashed, and a file
        // the project does not hold would report fresh against a hash a
        // record carries.
        const parsed = memq.parseAnchors('link/secret.js@' + HELLO_SHA);
        assert.deepStrictEqual(memq.anchorStatesFrom(parsed, root), [{
            path: 'link/secret.js', entry: 'link/secret.js@' + HELLO_SHA,
            recorded: HELLO_SHA, current: null, state: 'unreadable'
        }]);
    } finally {
        fs.rmSync(path.join(root, 'link'), { recursive: true, force: true });
        fs.rmSync(root, { recursive: true, force: true });
        fs.rmSync(outside, { recursive: true, force: true });
    }
});

test('a link inside the root is judged and never resolved, even where its target is a project file', (t) => {
    const root = makeAnchorTree();
    try {
        // The link's target is an ordinary file of this project, so following
        // it would land inside the root and every containment test would pass.
        // That is the point: containment runs on the result, so it cannot be
        // what decides whether to resolve. A path out of a record's text is
        // judged segment by segment on lstat instead, and a link is refused
        // where it is found rather than followed to see where it goes. What
        // makes that worth the refusal is the target this fixture is not: on
        // win32 a link to \\host\share turns the resolution into an outbound
        // SMB connection that authenticates as the logged-in account.
        try {
            fs.symlinkSync(path.join(root, 'src'), path.join(root, 'alias'), 'junction');
        } catch (err) {
            t.skip('this box refuses a junction: ' + err.code);
            return;
        }
        const states = memq.anchorStatesFrom(memq.parseAnchors('alias/a.js@' + HELLO_SHA), root);
        assert.deepStrictEqual(states, [{
            path: 'alias/a.js', entry: 'alias/a.js@' + HELLO_SHA,
            recorded: HELLO_SHA, current: null, state: 'unreadable'
        }], 'the link is not followed, so the anchor is unchecked rather than fresh');

        // The control: the same file by its own path is checked and fresh, so
        // the refusal above is the link and not the file.
        assert.deepStrictEqual(
            memq.anchorStatesFrom(memq.parseAnchors('src/a.js@' + HELLO_SHA), root),
            [{
                path: 'src/a.js', entry: 'src/a.js@' + HELLO_SHA,
                recorded: HELLO_SHA, current: HELLO_SHA, state: 'fresh'
            }]);
    } finally {
        fs.rmSync(path.join(root, 'alias'), { recursive: true, force: true });
        fs.rmSync(root, { recursive: true, force: true });
    }
});

test('a volume root is a root: containment takes the separator it already ends with', (t) => {
    // A checkout at a drive root realpaths to `D:\`, and a prefix built by
    // appending a second separator would put every file in the volume outside
    // its own root, reporting a whole store unreadable.
    const volume = path.parse(fs.realpathSync(os.tmpdir())).root;
    const file = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'memq-vol-')));
    try {
        fs.writeFileSync(path.join(file, 'a.js'), Buffer.from('hello\n', 'latin1'));
        const rel = path.relative(volume, path.join(file, 'a.js')).split(path.sep).join('/');
        if (!memq.isAnchorPath(rel)) {
            t.skip('this box\'s temp path is not spellable as an anchor: ' + rel);
            return;
        }
        const states = memq.anchorStatesFrom(memq.parseAnchors(rel + '@' + HELLO_SHA), volume);
        assert.deepStrictEqual(states,
            [{ path: rel, entry: rel + '@' + HELLO_SHA, recorded: HELLO_SHA, current: HELLO_SHA, state: 'fresh' }]);
    } finally {
        fs.rmSync(file, { recursive: true, force: true });
    }
});

test('anchorStatesFrom checks a parse a walk already holds, and anchorRoot is the one root derivation', () => {
    const store = makeStore();
    const root = makeAnchorTree();
    try {
        const raw = '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\n---\n\nbody\n';
        writeMemoryFile(store, 'anchored.md', raw);
        // A walk holding the record's text checks its anchors without a
        // second open, and answers what the file-reading form answers. This
        // is the composition the read surfaces copy, which is why it is the
        // one that carries every not-checked answer.
        assert.deepStrictEqual(
            memq.anchorStatesFrom(memq.frontmatterAnchors(raw), root),
            memq.anchorStates(path.join(store.memDir, 'anchored.md'), root));

        // An ordinary checkout has no worktree link, so the root is the
        // working directory itself. anchorRoot reads the environment for a
        // store pin, so the assertions that it answers a root and that a
        // record checks against it live in the spawned case below, where the
        // environment is the suite's rather than whatever ran it.
        assert.strictEqual(memq.worktreeMainRoot(root), null);
    } finally {
        fs.rmSync(root, { recursive: true, force: true });
        rmStore(store);
    }
});

test('a pinned store has no anchor root at all, and an unusable pin is the same answer', () => {
    // A pin names the project directory the store reads and writes, so its
    // records have no relationship to this working directory. Resolving their
    // anchors against cwd would hash whatever sits there and report every
    // anchored file in that store as deleted, and cwd is a perfectly good
    // absolute directory, so no later guard would catch it.
    //
    // Spawned rather than set here, because the pin is read from the
    // environment and no test in this file mutates this process's.
    const store = makeStore();
    try {
        const script = 'const m = require(' + JSON.stringify(MEMQ) + ');'
            + 'process.stdout.write(JSON.stringify([m.anchorRoot(process.cwd()), process.cwd()]));';
        const pinned = spawnSync(process.execPath, ['-e', script], {
            cwd: store.proj, encoding: 'utf8', env: childEnv(store, { KIT_MEMORY_PROJECT: 'pinned-one' })
        });
        assert.strictEqual(pinned.status, 0, pinned.stderr);
        assert.strictEqual(JSON.parse(pinned.stdout)[0], null);

        // An unusable pin resolves no store either, and the throw it raises
        // is not an answer a read surface may pass on.
        const broken = spawnSync(process.execPath, ['-e', script], {
            cwd: store.proj, encoding: 'utf8', env: childEnv(store, { KIT_MEMORY_PROJECT: '../escape' })
        });
        assert.strictEqual(broken.status, 0, broken.stderr);
        assert.strictEqual(JSON.parse(broken.stdout)[0], null);

        // The control, same spawn with no pin: the working directory is the
        // root, so the null above is the pin's doing and not the spawn's.
        const plain = spawnSync(process.execPath, ['-e', script], {
            cwd: store.proj, encoding: 'utf8', env: childEnv(store)
        });
        assert.strictEqual(plain.status, 0, plain.stderr);
        const [gotRoot, childCwd] = JSON.parse(plain.stdout);
        assert.strictEqual(gotRoot, childCwd);

        // And with that root in hand a record checks, so the derivation
        // feeds the reader rather than only answering a string. Spawned for
        // the same reason as the rest of this case: this process may itself
        // be running under a store pin.
        writeMemoryFile(store, 'anchored.md',
            '---\nname: ""\nanchors: a.js@' + HELLO_SHA + '\n---\n\nbody\n');
        fs.writeFileSync(path.join(store.proj, 'a.js'), Buffer.from('hello\n', 'latin1'));
        const checked = spawnSync(process.execPath, ['-e',
            'const m = require(' + JSON.stringify(MEMQ) + ');'
            + 'process.stdout.write(JSON.stringify(m.anchorStates('
            + JSON.stringify(path.join(store.memDir, 'anchored.md'))
            + ', m.anchorRoot(process.cwd()))));'], {
            cwd: store.proj, encoding: 'utf8', env: childEnv(store)
        });
        assert.strictEqual(checked.status, 0, checked.stderr);
        assert.deepStrictEqual(JSON.parse(checked.stdout), [{
            path: 'a.js', entry: 'a.js@' + HELLO_SHA,
            recorded: HELLO_SHA, current: HELLO_SHA, state: 'fresh'
        }]);
    } finally {
        rmStore(store);
    }
});

test('the frontmatter readers are exported, so the guard validates through memq and not a second parser', () => {
    for (const name of ['frontmatterBlock', 'frontmatterValue', 'frontmatterField',
        'readFrontmatterTags', 'frontmatterTags', 'readFrontmatterCreated', 'pinState',
        'supersedesName', 'frontmatterAnchors', 'readFrontmatterAnchors', 'parseAnchors',
        'isAnchorPath', 'blobSha', 'anchorStates', 'anchorStatesFrom', 'anchorRoot',
        'tierAnchorDrift', 'driftBlock',
        // The unread-block grammar and the repair it decides. The guard calls
        // frontmatterUnclosedRepair for the refusal it writes, so the store's
        // rule about which repair a record needs is stated once and the write
        // door and the read doors cannot come apart on it; the shape it
        // branches on and the file-reading wrapper are exported beside it for
        // the doors in memq.js and for any later reader of this state.
        'frontmatterUnclosedShape', 'frontmatterUnclosedRepair',
        'readFrontmatterUnclosedRepair']) {
        assert.strictEqual(typeof memq[name], 'function', name + ' is exported');
    }
    // The bounds a refusal names. A writer spelling 32 or 256 of its own is
    // how a message comes to state a limit the reader does not enforce.
    assert.strictEqual(memq.ANCHOR_PATH_CAP, 256);
    assert.strictEqual(memq.ANCHOR_ENTRIES_MAX, 32);
    assert.strictEqual(memq.ANCHOR_READ_CAP, 4194304);
    // The answers a field read gives that are neither a value nor absence.
    // They are exported because a caller that must tell them apart has to do
    // it by identity rather than by re-deriving what they mean: the guard
    // compares against FRONTMATTER_INDENTED for its placement refusal, and
    // memq's own pin and pointer doors compare against all three.
    for (const name of ['FRONTMATTER_INDENTED', 'FRONTMATTER_UNREADABLE', 'FRONTMATTER_UNCLOSED']) {
        assert.strictEqual(typeof memq[name], 'symbol', name + ' is exported');
    }
    assert.strictEqual(memq.frontmatterValue('---\nx:\n  pinned: 2026-01-01\n---\n', 'pinned'),
        memq.FRONTMATTER_INDENTED);
    assert.strictEqual(memq.frontmatterField(path.join(os.tmpdir(), 'no-such-memq-record.md'), 'pinned'),
        memq.FRONTMATTER_UNREADABLE);
});

test('decay-scan names every drifted record, pinned included, and says so when there is none', () => {
    const store = makeStore();
    try {
        // The tree the anchors resolve against is the project cwd itself,
        // which is what anchorRoot derives without a pin.
        fs.mkdirSync(path.join(store.proj, 'src'), { recursive: true });
        fs.writeFileSync(path.join(store.proj, 'src', 'a.js'), Buffer.from('hello\n', 'latin1'));
        fs.writeFileSync(path.join(store.proj, 'src', 'kept.js'), Buffer.from('hello\n', 'latin1'));
        // One record drifted two ways at once, so the line carries both
        // lists; one pinned and drifted, because a pin exempts a record from
        // retirement and not from being unverified; one whose file still
        // hashes to what it recorded; and one that anchors nothing at all,
        // the control that keeps a clean line from being the absence of a
        // reader.
        writeMemoryFile(store, 'drifted.md', '---\nname: ""\nanchors: src/a.js@' + OTHER_SHA
            + ', src/gone.js@' + HELLO_SHA + '\n---\n\n# d\n');
        writeMemoryFile(store, 'pinned-drift.md', '---\nname: ""\npinned: 2026-07-01\n'
            + 'anchors: src/a.js@' + OTHER_SHA + '\n---\n\n# p\n');
        writeMemoryFile(store, 'fresh.md',
            '---\nname: ""\nanchors: src/kept.js@' + HELLO_SHA + '\n---\n\n# f\n');
        writeMemoryFile(store, 'plain.md', '# nothing anchored\n');
        // An anchor naming a directory is a check that could not be made
        // rather than a file that moved, so the record is listed apart from
        // the drifted ones and never among the clean.
        fs.mkdirSync(path.join(store.proj, 'lib'), { recursive: true });
        writeMemoryFile(store, 'unexaminable.md',
            '---\nname: ""\nanchors: lib@' + HELLO_SHA + '\n---\n\n# u\n');

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stderr,
            'memq: usage evidence: none (no usage.jsonl)\n'
            + 'memq: pinned: 1 memory exempt from decay\n'
            + 'memq: pinned  pinned-drift  idle 0d  applied never  edited ' + dateOf(new Date())
            + '  read never\n'
            + 'memq: anchor drift (project tier): 2 memories anchoring a file that changed or is gone, 1 record whose anchored file could not be examined\n'
            + 'memq: drift  drifted  changed: src/a.js  missing: src/gone.js\n'
            + 'memq: drift  pinned-drift  changed: src/a.js\n'
            + 'memq: drift  unexaminable  unreadable: lib\n'
            + pairsStoodDown(['project'])
            + 'memq: no decay candidates\n');
        // Drift nominates and never retires: stdout is the list a prune acts
        // on, and no flag of decay-prune's acts on a drift line.
        assert.strictEqual(res.stdout, '');

        // The same store with the recorded hashes corrected: the block says
        // there is none, which is a different sentence from saying nothing.
        writeMemoryFile(store, 'drifted.md', '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA
            + '\n---\n\n# d\n');
        writeMemoryFile(store, 'pinned-drift.md', '---\nname: ""\npinned: 2026-07-01\n'
            + 'anchors: src/a.js@' + HELLO_SHA + '\n---\n\n# p\n');
        fs.rmSync(path.join(store.memDir, 'unexaminable.md'));
        const clean = run(store, ['decay-scan']);
        assert.strictEqual(clean.status, 0, clean.stderr);
        assert.ok(clean.stderr.includes(NO_DRIFT), 'the clean answer is stated:\n' + clean.stderr);
        assert.ok(!clean.stderr.includes('memq: drift  '), 'and no record is named:\n' + clean.stderr);
    } finally {
        rmStore(store);
    }
});

test('a drift line caps its paths and its records with the remainder counted', () => {
    const store = makeStore();
    try {
        // Six anchored paths on one record and twelve drifted records, both
        // past their caps, so a line and a block each tail off rather than
        // growing with the store.
        const entries = [];
        for (let i = 0; i < 6; i++) entries.push('gone-' + i + '.js@' + HELLO_SHA);
        writeMemoryFile(store, 'many-paths.md',
            '---\nname: ""\nanchors: ' + entries.join(', ') + '\n---\n\n# m\n');
        for (let i = 0; i < 12; i++) {
            writeMemoryFile(store, 'rec-' + String(i).padStart(2, '0') + '.md',
                '---\nname: ""\nanchors: gone.js@' + HELLO_SHA + '\n---\n\n# r\n');
        }

        const res = run(store, ['decay-scan']);
        assert.strictEqual(res.status, 0, res.stderr);
        const lines = res.stderr.split('\n').filter((l) => l !== '');
        assert.strictEqual(lines[1], 'memq: anchor drift (project tier): 13 memories anchoring a file that changed or is gone');
        assert.strictEqual(lines[2],
            'memq: drift  many-paths  missing: gone-0.js, gone-1.js, gone-2.js, gone-3.js, and 2 more');
        assert.strictEqual(lines[11], 'memq: drift  rec-08  missing: gone.js');
        assert.strictEqual(lines[12], 'memq: drift  ... and 3 more');
    } finally {
        rmStore(store);
    }
});

test('a pinned store reports the drift block as not checked, never as clean', () => {
    const store = makeStore();
    const memDir = pinnedMemDir(store, PIN);
    try {
        // A pin names the project directory the store reads, which says
        // nothing about this working directory, so these records' paths
        // resolve against nothing. Saying so is the whole point: a scan that
        // said 'no anchor drift' here would report a store nobody checked as
        // verified.
        fs.mkdirSync(memDir, { recursive: true });
        fs.writeFileSync(path.join(memDir, 'anchored.md'),
            '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\n---\n\n# a\n', 'utf8');
        const res = run(store, ['decay-scan'], { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(res.status, 0, res.stderr);
        assert.ok(res.stderr.includes('memq: anchor drift (project tier): not checked (a store'
            + ' pin is in effect, so no root is derived from this working directory)\n'),
            'the rootless cause is named:\n' + res.stderr);
        assert.ok(!res.stderr.includes(NO_DRIFT), 'not checked is never the clean answer:\n' + res.stderr);
    } finally {
        rmStore(store);
    }
});

test('get states each anchor after the body, and names the cause when it could not check', () => {
    const store = makeStore();
    try {
        fs.mkdirSync(path.join(store.proj, 'src'), { recursive: true });
        fs.writeFileSync(path.join(store.proj, 'src', 'a.js'), Buffer.from('hello\n', 'latin1'));
        fs.writeFileSync(path.join(store.proj, 'src', 'changed.js'), Buffer.from('hello\n', 'latin1'));
        // All four states from one record: the file that still hashes to what
        // was recorded, the one that does not, the one that is gone, and the
        // directory, which is a check that could not be made rather than a
        // deletion.
        const body = '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + ', src/changed.js@' + OTHER_SHA
            + ', src/gone.js@' + HELLO_SHA + ', src@' + HELLO_SHA + '\n---\n\n# anchored\n';
        writeMemoryFile(store, 'anchored.md', body);

        const got = run(store, ['get', 'anchored']);
        assert.strictEqual(got.status, 0, got.stderr);
        assert.strictEqual(got.stdout, body
            + 'anchors: src/a.js fresh\n'
            + 'anchors: src/changed.js changed (recorded ' + OTHER_SHA.slice(0, 7)
            + ', now ' + HELLO_SHA.slice(0, 7) + ')\n'
            + 'anchors: src/gone.js missing\n'
            + 'anchors: src unreadable\n');

        // A record that anchors nothing says nothing: there is no state to
        // report, and the read that established it needed no root.
        const plainBody = '# plain\n';
        writeMemoryFile(store, 'plain.md', plainBody);
        const plain = run(store, ['get', 'plain']);
        assert.strictEqual(plain.status, 0, plain.stderr);
        assert.strictEqual(plain.stdout, plainBody);

        // A frontmatter block that opens and never closes is read by nothing,
        // so what the record anchors is unknown and the line says which cause
        // it was rather than printing no anchors. Both fields answer for
        // themselves on such a record: one line saying the anchors went
        // unchecked leaves the triggers reading as a record that declares
        // none, which is the false-clean answer this surface exists to
        // refuse.
        const openBody = '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\nstill open\n';
        writeMemoryFile(store, 'unterminated.md', openBody);
        const unread = run(store, ['get', 'unterminated']);
        assert.strictEqual(unread.status, 0, unread.stderr);
        assert.strictEqual(unread.stdout, openBody
            + 'anchors: not checked (this record\'s frontmatter could not be read)\n'
            + 'triggers: not listed (this record\'s frontmatter could not be read)\n');
    } finally {
        rmStore(store);
    }
});

test('get says a pinned store checked no anchors, and stays silent for a record with none', () => {
    const store = makeStore();
    const memDir = pinnedMemDir(store, PIN);
    const projB = makeSecondProject();
    try {
        fs.mkdirSync(memDir, { recursive: true });
        fs.writeFileSync(path.join(memDir, 'anchored.md'),
            '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\n---\n\n# a\n', 'utf8');
        fs.writeFileSync(path.join(memDir, 'plain.md'), '# plain\n', 'utf8');

        const got = runFrom(store, projB, ['get', 'anchored'], { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(got.status, 0, got.stderr);
        assert.ok(got.stdout.endsWith('anchors: not checked (a store pin is in effect, so no root'
            + ' is derived from this working directory)\n'),
            'the record that anchors something says it went unchecked:\n' + got.stdout);

        // The record naming no anchor is silent even here: what it declares
        // is read from its own frontmatter, which needs no root, so nothing
        // about it is unverified.
        const plain = runFrom(store, projB, ['get', 'plain'], { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(plain.status, 0, plain.stderr);
        assert.ok(!plain.stdout.includes('anchors:'), 'nothing to check, nothing said:\n' + plain.stdout);
    } finally {
        rmStore(store);
        try { fs.rmSync(projB, { recursive: true, force: true }); } catch { /* best effort */ }
    }
});

// anchorReport answers the pin cause for a pinned session whether or not
// cwd names a network share: under a pin, anchorRoot(cwd) answers null
// before it ever touches cwd's filesystem shape, so the network share
// plays no part in why no root resolved, and naming it instead would
// prescribe a remedy that cannot work (moving off the share changes
// nothing while the pin stands, Standing Amendments 6 and 7). This asserts
// pinned+network reads exactly as pinned+local.
//
// The network-shaped cwd is a real, locally reachable administrative-share
// path (localUncPath), so this case costs no SMB timeout to prove. That
// spelling resolves only on win32, and only with local-admin rights on this
// machine (the C$-style share); off win32 the path is not this machine's
// own directory and the case fails for an environment reason rather than a
// code one.
test('get names the pin cause for a pinned session whether or not cwd names a network share',
    { skip: process.platform !== 'win32' ? 'an admin-share UNC path is a win32 shape'
        : localUncPathAvailable() ? false : 'administrative shares are not reachable on this machine' },
    () => {
    const store = makeStore();
    const memDir = pinnedMemDir(store, PIN);
    try {
        fs.mkdirSync(memDir, { recursive: true });
        const body = '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\n---\n\n# a\n';
        fs.writeFileSync(path.join(memDir, 'anchored.md'), body, 'utf8');

        const networked = runFrom(store, localUncPath(store.proj), ['get', 'anchored'],
            { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(networked.status, 0, networked.stderr);
        assert.ok(networked.stdout.endsWith('anchors: not checked (a store pin is in effect, so no'
            + ' root is derived from this working directory)\n'),
            'the pin cause, not the network cause:\n' + networked.stdout);

        // The control: the same fixture, the same pin, an ordinary local
        // cwd. Only cwd's shape differs, and this proves the two now answer
        // identically rather than the network case losing the pin answer.
        const local = runFrom(store, store.proj, ['get', 'anchored'], { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(local.status, 0, local.stderr);
        assert.strictEqual(local.stdout, networked.stdout,
            'a network-shaped cwd changes nothing under a pin:\nlocal:\n' + local.stdout
                + '\nnetworked:\n' + networked.stdout);
    } finally {
        rmStore(store);
    }
});

// Standing Amendment 7's cell table for get: every state the emitting path
// admits, each cell's exit code and its answer's own first (and here only)
// not-checked line.
//
//   unpinned + local     ordinary: the anchor's own state line (ANCHOR_CAUSE
//                        does not apply; ready fixture below reads 'fresh')
//   unpinned + network   the hoist ahead of readMemDirOrNote: exit 0,
//                        stderr names the network share, stdout empty
//   pinned   + local     the pin cause: exit 0, stdout ends 'a store pin is
//                        in effect, so no root is derived...'
//   pinned   + network   the same pin cause, byte-identical to the cell
//                        above: the pin is the whole account of why no root
//                        was derived, and the working directory's shape
//                        adds nothing to it
test("get's four cwd/pin cells: exit code and first not-checked line",
    { skip: process.platform !== 'win32' ? 'an admin-share UNC path is a win32 shape'
        : localUncPathAvailable() ? false : 'administrative shares are not reachable on this machine' },
    () => {
    const store = makeStore();
    const pinnedDir = pinnedMemDir(store, PIN);
    try {
        const body = '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\n---\n\n# a\n';
        fs.mkdirSync(store.memDir, { recursive: true });
        fs.writeFileSync(path.join(store.memDir, 'anchored.md'), body, 'utf8');
        fs.mkdirSync(pinnedDir, { recursive: true });
        fs.writeFileSync(path.join(pinnedDir, 'anchored.md'), body, 'utf8');
        fs.mkdirSync(path.join(store.proj, 'src'), { recursive: true });
        fs.writeFileSync(path.join(store.proj, 'src', 'a.js'), Buffer.from('hello\n', 'latin1'));

        const unpinnedLocal = run(store, ['get', 'anchored']);
        assert.strictEqual(unpinnedLocal.status, 0, unpinnedLocal.stderr);
        assert.ok(unpinnedLocal.stdout.endsWith('anchors: src/a.js fresh\n'),
            'unpinned+local: an ordinary fresh answer:\n' + unpinnedLocal.stdout);

        const unpinnedNetwork = runFrom(store, localUncPath(store.proj), ['get', 'anchored'], {});
        assert.strictEqual(unpinnedNetwork.status, 0, unpinnedNetwork.stderr);
        assert.strictEqual(unpinnedNetwork.stdout, '');
        assert.strictEqual(unpinnedNetwork.stderr, 'memq: this call\'s working directory names a '
            + 'network share, so its project memory directory was not resolved (a synchronous walk '
            + 'under it risks hanging for the SMB timeout on an unreachable host); nothing to report\n');

        const pinnedLocal = runFrom(store, store.proj, ['get', 'anchored'], { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(pinnedLocal.status, 0, pinnedLocal.stderr);
        assert.ok(pinnedLocal.stdout.endsWith('anchors: not checked (a store pin is in effect, so no'
            + ' root is derived from this working directory)\n'));

        const pinnedNetwork = runFrom(store, localUncPath(store.proj), ['get', 'anchored'],
            { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(pinnedNetwork.status, 0, pinnedNetwork.stderr);
        assert.strictEqual(pinnedNetwork.stdout, pinnedLocal.stdout,
            'pinned+network is byte-identical to pinned+local');
    } finally {
        rmStore(store);
    }
});

// Every other network test above pins KIT_MEMORY_PROJECT, which routes
// project-tier resolution off the pin and never touches cwd's filesystem
// shape at all, so none of those cases exercise the hoist below. This is
// the unpinned control: no KIT_MEMORY_PROJECT, an ordinary reachable
// directory spelled through the same administrative-share UNC form
// localUncPath uses elsewhere, so the case is fast and deterministic
// rather than paying a real SMB timeout, while still reading as
// network-shaped to namesNetworkShare's leading-separator test exactly as
// an unreachable share would.
test('get stands the whole command down for an unpinned network working directory, before its '
        + 'project memory directory is ever resolved',
    { skip: process.platform !== 'win32' ? 'an admin-share UNC path is a win32 shape'
        : localUncPathAvailable() ? false : 'administrative shares are not reachable on this machine' },
    () => {
    const store = makeStore();
    try {
        const res = runFrom(store, localUncPath(store.proj), ['get', 'anything'], {});
        assert.strictEqual(res.status, 0, res.stderr);
        assert.strictEqual(res.stdout, '');
        assert.strictEqual(res.stderr, 'memq: this call\'s working directory names a network '
            + 'share, so its project memory directory was not resolved (a synchronous walk under '
            + 'it risks hanging for the SMB timeout on an unreachable host); nothing to report\n');
    } finally {
        rmStore(store);
    }
});

test('recall marks a drifted record, leaves a fresh one plain, and carries both labels at once', () => {
    const store = makeStore();
    try {
        fs.mkdirSync(path.join(store.proj, 'src'), { recursive: true });
        fs.writeFileSync(path.join(store.proj, 'src', 'a.js'), Buffer.from('hello\n', 'latin1'));
        const d5 = daysAgo(5);
        writeMemoryFile(store, 'drifted.md',
            '---\nname: ""\nanchors: src/a.js@' + OTHER_SHA + '\n---\n\n# d\n');
        // Superseded and drifted at once: two facts about one record, in a
        // declared order so no two lines disagree about where each sits.
        writeMemoryFile(store, 'both.md',
            '---\nname: ""\nanchors: src/gone.js@' + HELLO_SHA + '\n---\n\n# b\n');
        writeMemoryFile(store, 'successor.md', '---\nsupersedes: both\n---\n# s\n');
        writeMemoryFile(store, 'fresh.md',
            '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\n---\n\n# f\n');
        // An anchor naming a directory is a check that could not be made,
        // which is not a fresh anchor either.
        fs.mkdirSync(path.join(store.proj, 'lib'), { recursive: true });
        writeMemoryFile(store, 'unexaminable.md',
            '---\nname: ""\nanchors: lib@' + HELLO_SHA + '\n---\n\n# u\n');
        // A record no reader can read is not a record whose anchors are
        // fresh, and the digest says so with its own token.
        writeMemoryFile(store, 'unterminated.md',
            '---\nname: ""\nanchors: src/a.js@' + HELLO_SHA + '\nstill open\n');
        for (const name of ['drifted.md', 'both.md', 'successor.md', 'fresh.md',
            'unterminated.md', 'unexaminable.md']) {
            setMtime(store, name, d5);
        }

        const res = run(store, ['recall']);
        assert.strictEqual(res.status, 0, res.stderr);
        const lines = res.stdout.split('\n');
        assert.ok(lines.includes('project  both  applied never  alive 5d  superseded by successor  [drift]'),
            'the supersession label leads and the drift token follows it:\n' + res.stdout);
        assert.ok(lines.includes('project  drifted  applied never  alive 5d  [drift]'), res.stdout);
        assert.ok(lines.includes('project  fresh  applied never  alive 5d'),
            'a record whose anchored file still hashes the same is plain:\n' + res.stdout);
        assert.ok(lines.includes('project  successor  applied never  alive 5d'), res.stdout);
        assert.ok(lines.includes('project  unexaminable  applied never  alive 5d  [drift?]'),
            'an anchor nobody could examine is marked apart from a fresh one:\n' + res.stdout);
        assert.ok(lines.includes('project  unterminated  applied never  alive 5d  [drift?]'),
            'a record nobody could read is marked apart from both:\n' + res.stdout);
    } finally {
        rmStore(store);
    }
});

test('recall carries no drift token under a store pin, where no root resolves', () => {
    const store = makeStore();
    const memDir = pinnedMemDir(store, PIN);
    const projB = makeSecondProject();
    try {
        // The same record that reads as drifted without a pin: under one, the
        // check is skipped rather than resolved against a working directory
        // the pin says nothing about, which would call every anchored file
        // deleted.
        fs.mkdirSync(memDir, { recursive: true });
        fs.writeFileSync(path.join(memDir, 'drifted.md'),
            '---\nname: ""\nanchors: src/a.js@' + OTHER_SHA + '\n---\n\n# d\n', 'utf8');
        const pinned = runFrom(store, projB, ['recall'], { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(pinned.status, 0, pinned.stderr);
        assert.ok(!pinned.stdout.includes('[drift'), 'no token at all under a pin:\n' + pinned.stdout);

        // A digest whose lines all read unlabeled, with nothing saying the
        // check never ran, is a clean report of an unchecked tier, so the
        // tier's own line carries what the tokens cannot.
        assert.match(pinned.stdout, /^project tier: .*, anchors not checked \(a store pin is in effect, so no root is derived from this working directory\)$/m);

        // The control, the same bytes in the cwd-derived tier with no pin:
        // the token is there, so the silence above is the pin and not the
        // fixture.
        writeMemoryFile(store, 'drifted.md',
            '---\nname: ""\nanchors: src/a.js@' + OTHER_SHA + '\n---\n\n# d\n');
        fs.writeFileSync(path.join(store.proj, 'src.js'), Buffer.from('hello\n', 'latin1'));
        const plain = run(store, ['recall']);
        assert.strictEqual(plain.status, 0, plain.stderr);
        assert.match(plain.stdout, /^project  drifted  applied never  alive \S+  \[drift\]$/m);
    } finally {
        rmStore(store);
        try { fs.rmSync(projB, { recursive: true, force: true }); } catch { /* best effort */ }
    }
});

// recall's project-tier drift line answers the pin cause for a pinned
// session whether or not cwd names a network share: anchorRoot(cwd)
// answers null for a pin before it ever touches cwd's filesystem shape, so
// the share plays no part in why no root resolved, and naming it instead
// would prescribe a remedy (move off the share) that cannot work while the
// pin stands (Standing Amendments 6 and 7). This asserts pinned+network
// reads exactly as pinned+local.
//
// The pin is what keeps this fixture's own store resolution off cwd
// (Section 3's existing behavior); localUncPath is what keeps the child
// fast rather than costing a real SMB timeout to prove it. That spelling
// resolves only on win32, and only with local-admin rights on this machine
// (the C$-style share); off win32 the path is not this machine's own
// directory and the case fails for an environment reason rather than a
// code one.
test('recall names the pin cause for a pinned session whether or not cwd names a network share',
    { skip: process.platform !== 'win32' ? 'an admin-share UNC path is a win32 shape'
        : localUncPathAvailable() ? false : 'administrative shares are not reachable on this machine' },
    () => {
    const store = makeStore();
    const memDir = pinnedMemDir(store, PIN);
    try {
        fs.mkdirSync(memDir, { recursive: true });
        fs.writeFileSync(path.join(memDir, 'drifted.md'),
            '---\nname: ""\nanchors: src/a.js@' + OTHER_SHA + '\n---\n\n# d\n', 'utf8');

        const network = runFrom(store, localUncPath(store.proj), ['recall'], { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(network.status, 0, network.stderr);
        assert.ok(!network.stdout.includes('[drift'), 'no token under either cause:\n' + network.stdout);
        assert.match(network.stdout,
            /^project tier: .*, anchors not checked \(a store pin is in effect, so no root is derived from this working directory\)$/m,
            'the pin cause, not the network cause:\n' + network.stdout);
        assert.ok(!network.stdout.includes('names a network share'),
            'the network cause must not also appear:\n' + network.stdout);

        // The control: the same fixture, the same pin, an ordinary local
        // cwd. Only cwd's shape differs, and this proves the two now answer
        // identically.
        const local = runFrom(store, store.proj, ['recall'], { KIT_MEMORY_PROJECT: PIN });
        assert.strictEqual(local.status, 0, local.stderr);
        assert.strictEqual(local.stdout, network.stdout,
            'a network-shaped cwd changes nothing under a pin:\nlocal:\n' + local.stdout
                + '\nnetworked:\n' + network.stdout);
    } finally {
        rmStore(store);
    }
});

// Standing Amendment 7's cell table for recall: every state the emitting
