        writeMemoryFile(store, 'drifted.md',
            '---\nname: ""\nanchors: src/a.js@' + OTHER_SHA + '\n---\n\n# d\n');
        fs.mkdirSync(pinnedDir, { recursive: true });
        fs.writeFileSync(path.join(pinnedDir, 'pinned.md'), '---\nname: ""\n---\n\n# p\n', 'utf8');

