        writeMemoryFile(store, 'go.md', '# goes\n');
        writeMemoryFile(store, 'MEMORY.md', '# Memory Index\n\n- [Stay](stay.md) - a live fact\n');

        const res = run(store, ['decay-prune', '--archive', 'go']);
