        writeMemoryFile(store, 'a-fact.md', '# a\n');
        const res = run(store, ['recent'], { NODE_OPTIONS: refuseMemDirListPreload(store.root) });
        assert.strictEqual(res.status, 0, 'an unlistable tier never fails the digest');
