        assert.strictEqual(run(store, ['add-operator', 'op-tagged', 'tagged fact', '--tag', 'sql']).status, 0);
        assert.strictEqual(run(store, ['add-operator', 'op-plain', 'plain fact']).status, 0);
        const res = run(store, ['find', 'op', '--tag', 'sql']);
